"""Compare two executable GQL benchmark JARs with the repository's supported JMH helper."""
from pathlib import Path
import argparse
import hashlib
import json
import os
import shutil
import subprocess
import time

ROOT = next(parent for parent in Path(__file__).resolve().parents
            if (parent / "scripts/run-single-benchmark.sh").is_file())
CASES = [
    ("property-named-1", "PROPERTY_FILTER", "NAMED", 1, 32, "countPaths"),
    ("property-named-64", "PROPERTY_FILTER", "NAMED", 64, 32, "countPaths"),
    ("property-named-256", "PROPERTY_FILTER", "NAMED", 256, 32, "countPaths"),
    ("property-merged-64", "PROPERTY_FILTER", "MERGED", 64, 32, "countPaths"),
    ("topology-merged-64", "TOPOLOGY", "MERGED", 64, 32, "countPaths"),
    ("topology-named-64", "TOPOLOGY", "NAMED", 64, 32, "countPaths"),
    ("topology-merged-fanout128", "TOPOLOGY", "MERGED", 1, 128, "countPaths"),
    ("label-named-64", "LABEL", "NAMED", 64, 32, "countPaths"),
    ("next-union-named-64", "NEXT_UNION", "NAMED", 64, 32, "countPaths"),
    ("prepare-property-named-64", "PROPERTY_FILTER", "NAMED", 64, 32, "prepareAndCountPaths"),
]

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--before-jar", type=Path, required=True)
parser.add_argument("--after-jar", type=Path, required=True)
parser.add_argument("--output", type=Path, required=True)
parser.add_argument("--jdk", type=Path, required=True)
parser.add_argument("--case", action="append", choices=[c[0] for c in CASES])
args = parser.parse_args()
output = args.output.resolve()
output.mkdir(parents=True, exist_ok=False)
before = args.before_jar.resolve()
after = args.after_jar.resolve()
target = ROOT / "core/sail/lmdb/target/jmh-benchmarks.jar"
original = output / "original-benchmark.jar"
shutil.copyfile(target, original)
env = os.environ.copy()
env["JAVA_HOME"] = str(args.jdk.resolve())
env["PATH"] = str(args.jdk.resolve() / "bin") + os.pathsep + env["PATH"]
temporary = output / "tmp"
temporary.mkdir()
env["JAVA_TOOL_OPTIONS"] = "-Djava.io.tmpdir=" + str(temporary)
records = []
artifacts = {label: {"sha256": hashlib.sha256(path.read_bytes()).hexdigest(), "bytes": path.stat().st_size}
             for label, path in [("before", before), ("after", after)]}
(output / "artifacts.json").write_text(json.dumps(artifacts, indent=2) + "\n")
try:
    for index, case in enumerate(CASES):
        name, workload, graph, roots, fanout, method = case
        if args.case and name not in args.case:
            continue
        # Alternate order across cases to reduce a consistent before/after time-order bias.
        variants = [("before", before), ("after", after)]
        if index % 2:
            variants.reverse()
        for variant, jar in variants:
            shutil.copyfile(jar, target)
            stem = f"{name}-{variant}"
            result_path = output / (stem + ".json")
            command = ["scripts/run-single-benchmark.sh", "--no-build", "--module", "core/sail/lmdb",
                       "--class", "org.eclipse.rdf4j.sail.lmdb.benchmark.GqlAdjacencyQueryBenchmark",
                       "--method", method, "--warmup-iterations", "10", "--measurement-iterations", "5",
                       "--forks", "2"]
            for param in ["language=GQL", "adjacency=PREFER", "graph=" + graph, "fanout=" + str(fanout),
                          "rootCount=" + str(roots), "nativeEvaluation=true", "workload=" + workload]:
                command.extend(["--param", param])
            for option in ["-Xms512m", "-Xmx2g"]:
                command.extend(["--jvm-arg", option])
            for option in ["-t", "1", "-w", "2s", "-r", "2s", "-prof", "gc", "-rf", "json",
                           "-rff", str(result_path), "-foe", "true"]:
                command.extend(["--jmh-arg", option])
            start = time.time()
            print(f"START {stem}", flush=True)
            with (output / (stem + ".log")).open("w") as log:
                completed = subprocess.run(command, cwd=ROOT, env=env, stdout=log, stderr=subprocess.STDOUT)
            shutil.copyfile(ROOT / "core/sail/lmdb/target/benchmark-output.log", output / (stem + ".full.log"))
            record = {"case": name, "variant": variant, "command": command,
                      "elapsed_seconds": round(time.time() - start, 3), "exit_code": completed.returncode}
            records.append(record)
            (output / "commands.json").write_text(json.dumps(records, indent=2) + "\n")
            if completed.returncode:
                raise SystemExit(completed.returncode)
            result = json.loads(result_path.read_text())
            if len(result) != 1:
                raise RuntimeError(f"Expected one pinned result, got {len(result)}")
            metric = result[0]["primaryMetric"]
            print(f"DONE {stem}: {metric['score']:.3f} +/- {metric['scoreError']:.3f} {metric['scoreUnit']}", flush=True)
finally:
    shutil.copyfile(original, target)
